'use strict';
const STUDY_PATHS={
 'Computer Science':['Programming & problem-solving','Data, networks & systems','Software project studio'],
 Engineering:['Engineering mathematics','Design & practical systems','Prototype studio'],
 Medicine:['Foundations of medical science','Ethics & communication','Research practice'],
 Nursing:['Foundations of care','Professional communication','Research practice'],
 Law:['Legal reasoning','Research & written argument','Moot-court practice'],
 Pharmacy:['Pharmaceutical foundations','Professional ethics','Laboratory study skills'],
 Agriculture:['Food & agricultural systems','Sustainable enterprise','Field-study planning'],
 'Business Administration':['Business foundations','Finance & decision-making','Enterprise project'],
 'Arts & Sciences':['Critical thinking','Research & communication','Creative project studio']
};
const JOURNEY_STORIES=[
 {id:'welcome',day:2,title:'A seat at the table',text:'Dami is organising a small study circle. You have your own plan for the afternoon. How do you begin?',choices:[{id:'together',label:'Make space for the study circle',effect:{social:10,knowledge:4},rep:2},{id:'independent',label:'Build a focused independent routine',effect:{knowledge:8,mood:3},rep:1}]},
 {id:'team',day:8,title:'The group-project moment',text:'Your group needs someone to turn scattered ideas into a plan.',choices:[{id:'lead',label:'Coordinate the tasks and listen to everyone',effect:{skills:8,social:6,energy:-3},rep:4},{id:'build',label:'Take responsibility for a practical piece',effect:{skills:11,knowledge:4},rep:2}]},
 {id:'budget',day:15,title:'The mid-semester invitation',text:'A friend suggests an extra outing. You also have supplies to buy. What matters most this week?',choices:[{id:'save',label:'Suggest a free campus catch-up',effect:{mood:7,social:8},rep:2},{id:'treat',label:'Enjoy a small planned treat · ₦500',cost:500,effect:{mood:16,social:5},rep:1}]},
 {id:'setback',day:22,title:'A draft that did not land',text:'Your latest practice presentation was rough. This is a chance to choose your next move.',choices:[{id:'feedback',label:'Ask for specific feedback and revise',effect:{knowledge:8,skills:6},rep:3},{id:'reset',label:'Take a short reset, then practise again',effect:{mood:12,skills:5},rep:2}]},
 {id:'legacy',day:27,title:'Leave something useful behind',text:'A new student asks what you wish you had known at the beginning of the semester.',choices:[{id:'guide',label:'Write a small study-and-campus guide',effect:{knowledge:5,social:8,skills:4},rep:4},{id:'mentor',label:'Offer encouragement and a listening ear',effect:{mood:10,social:12},rep:4}]}
];
function ensureJourney(){const s=ensureStudentState();if(!s.journey||typeof s.journey!=='object')s.journey={};const j=s.journey;
 if(!Number.isInteger(j.semester)||j.semester<1||j.semester>8)j.semester=1;
 if(!Array.isArray(j.transcript))j.transcript=[];if(!j.mastery||typeof j.mastery!=='object')j.mastery={};if(!j.choices||typeof j.choices!=='object')j.choices={};return j}
function semesterLabel(){const j=ensureJourney();return `${Math.ceil(j.semester/2)}00 LEVEL · SEMESTER ${j.semester%2?1:2}`}
function journeyCGPA(){const t=ensureJourney().transcript;return t.length?t.reduce((n,r)=>n+r.gpa,0)/t.length:0}
function courseTopics(){return STUDY_PATHS[state.course]||STUDY_PATHS['Arts & Sciences']}
function recordSemester(){if(!state.finished||!Number.isFinite(state.finalGpa))return;const j=ensureJourney();if(j.transcript.some(r=>r.semester===j.semester))return;
 j.transcript.push({semester:j.semester,gpa:Math.max(0,Math.min(5,state.finalGpa)),lectures:state.attendance,assignments:state.assignments,projects:Object.values(ensureStudentState().projects).filter(p=>p.submitted).length,mastery:courseTopics().map((name,i)=>({name,score:j.mastery[i]||0}))});
 notifyStudent(j.semester===8?'Your fictional eight-semester journey is complete.':`Semester ${j.semester} results saved to your transcript.`)}
function startNextSemester(){if(!state.finished)return;recordSemester();const j=ensureJourney();if(j.semester>=8){toast('Your game journey is complete. You can review it or start a new character.');return}
 show(`<div class="eyebrow">YOUR NEXT CHAPTER</div><h2>Continue to semester ${j.semester+1}?</h2><p>Your character, money, savings, skills, friendships, inventory, outfits and room upgrades stay with you. The 28-day calendar, attendance, assignments, projects and daily limits restart.</p><p>Each semester is equally weighted in this fictional game transcript. This is not ABUAD’s official curriculum or progression system.</p><button class="primary" id="confirmNextSemester">Begin the next semester →</button><button class="secondary" id="cancelNextSemester">Stay with my results</button>`);
 $('#cancelNextSemester').onclick=results;$('#confirmNextSemester').onclick=()=>{if(!state.finished)return;const s=ensureStudentState();j.semester++;j.mastery={};state.day=1;state.hour=8;state.finished=false;delete state.finalGpa;state.attendance=0;state.assignments=0;state.knowledge=15;state.energy=s.owned.includes('bed')?98:90;state.hunger=80;state.mood=clamp(state.mood+10);state.location='hostel';state.daily={};s.projects={};s.quizDays=[];s.eventDays=[];s.scholarship=false;s.hygiene=85;s.bladder=85;s.tick=0;close();selected='hostel';tab='life';studentCommit(`Began semester ${j.semester}. A fresh chapter with the same character.`)}}
function studyCourse(index){const j=ensureJourney();if(!Number.isInteger(index)||index<0||index>=courseTopics().length||state.finished)return;if(state.daily['course'+index]){toast('One focused session per course per day.');return}if((j.mastery[index]||0)>=100){toast('This course pathway is mastered for this semester.');return}if(!studentSpendTime(2,-12))return;state.daily['course'+index]=true;j.mastery[index]=clamp((j.mastery[index]||0)+10);state.knowledge=clamp(state.knowledge+5+(ensureStudentState().owned.includes('desk')?2:0));studentCommit(`Studied ${courseTopics()[index]}.`,'journey')}
function storyKey(id){return ensureJourney().semester+':'+id}
function chooseJourneyStory(id,choiceId){const story=JOURNEY_STORIES.find(x=>x.id===id),choice=story?.choices.find(x=>x.id===choiceId),j=ensureJourney();if(!story||!choice||state.finished||state.day<story.day||j.choices[storyKey(id)])return;
 if(!studentSpendTime(1,-4,choice.cost||0))return;j.choices[storyKey(id)]=choice.id;effect(choice.effect);ensureStudentState().reputation+=choice.rep;studentCommit(story.title+': '+choice.label.replace(/ · .*/,''),'journey')}
function journeyContent(){recordSemester();const j=ensureJourney();return `<div class="journey-summary"><span>${semesterLabel()}</span><h3>${j.semester===8&&state.finished?'Your campus story, complete.':'A bigger story, one semester at a time.'}</h3><p>${j.transcript.length} completed semesters · ${j.transcript.length?'Game CGPA '+journeyCGPA().toFixed(2)+' / 5':'Your transcript begins after your first finals.'}</p><div class="journey-steps">${Array.from({length:8},(_,i)=>`<span class="${i+1<j.semester?'done':i+1===j.semester?'current':''}">${i+1}</span>`).join('')}</div>${state.finished&&j.semester<8?phoneButton('Continue to semester '+(j.semester+1),'id="journeyContinue"',false).replace('disabled',''):''}</div><p class="phone-note">An eight-semester game arc for every character, not the real duration, curriculum or academic rules of any department.</p><h3>Your ${escapeHtml(state.course)} pathway</h3>${courseTopics().map((name,i)=>`<div class="phone-row"><b>${escapeHtml(name)}</b><small>Mastery ${j.mastery[i]||0} / 100 · +5 knowledge per session; a study desk adds +2</small><div class="bar" style="margin-top:10px"><span style="width:${j.mastery[i]||0}%"></span></div>${phoneButton(state.daily['course'+i]?'Studied today ✓':'Focused session · 2 hrs',`data-study-course="${i}"`,state.daily['course'+i]||(j.mastery[i]||0)>=100)}</div>`).join('')}<h3>Choices that shape your story</h3>${JOURNEY_STORIES.map(story=>{const picked=j.choices[storyKey(story.id)],locked=state.day<story.day;let text=story.text;if(story.id==='team'&&j.choices[storyKey('welcome')]==='together')text='The study-circle friends you made earlier ask you to help organise their next group project.';if(story.id==='legacy'&&j.choices[storyKey('team')]==='lead')text='A new student heard how you brought your project group together and asks for advice.';return `<div class="phone-row"><b>${story.title}</b><small>${picked?'Your choice is part of this semester’s story.':locked?'Unlocks on day '+story.day:'A campus moment · 1 game hour'}</small><p>${escapeHtml(text)}</p>${picked?`<span class="pill">✓ ${escapeHtml(story.choices.find(c=>c.id===picked)?.label||'Choice saved')}</span>`:story.choices.map(c=>phoneButton(c.label,`data-story="${story.id}" data-story-choice="${c.id}"`,locked)).join('')}</div>`}).join('')}<h3>Your fictional transcript</h3>${j.transcript.length?j.transcript.map(r=>`<div class="phone-row"><b>Semester ${r.semester} · GPA ${r.gpa.toFixed(2)} / 5</b><small>${r.lectures} lectures · ${r.assignments} assignments · ${r.projects} planner projects</small></div>`).join(''):'<p>Complete day 28 to record your first semester.</p>'}<p class="phone-note">Game CGPA is the simple average of completed semester GPAs, not a credit-weighted university transcript.</p>`}
function renderJourneyExtras(){const j=ensureJourney();const tag=$('#profile .student-tag');if(tag)tag.textContent='✦ '+semesterLabel();if(state.finished)recordSemester();if(tab==='goals'||tab==='life'){if(tab==='goals'){const card=$('#content .map-head h2');if(card)card.textContent='Semester '+j.semester}const open=document.createElement('button');open.className='secondary';open.textContent='🎓 '+semesterLabel()+' · My journey & transcript →';open.onclick=()=>openStudentPhone('journey');$('#content').prepend(open)}}
function bindJourney(){document.querySelectorAll('[data-study-course]').forEach(b=>b.onclick=()=>studyCourse(Number(b.dataset.studyCourse)));document.querySelectorAll('[data-story-choice]').forEach(b=>b.onclick=()=>chooseJourneyStory(b.dataset.story,b.dataset.storyChoice));if(state.finished&&ensureJourney().semester<8){const b=$('#journeyContinue');if(b)b.onclick=()=>{close();startNextSemester()}}}
PHONE_APPS.push(['journey','🎓','My journey','Courses, choices & your next semester.']);

// Extend the existing, save-compatible game after it has initialised.
const journeyBaseAppContent=phoneAppContent;
phoneAppContent=function(app){return app==='journey'?journeyContent():journeyBaseAppContent(app)};
const journeyBasePhoneBindings=bindPhone;
bindPhone=function(app){journeyBasePhoneBindings(app);if(app==='journey')bindJourney()};
const journeyBaseRender=render;
render=function(){journeyBaseRender();if(state)renderJourneyExtras()};
const journeyBaseSave=save;
save=function(){if(state){ensureJourney();if(state.finished)recordSemester()}journeyBaseSave()};
const journeyBaseResults=results;
results=function(){recordSemester();journeyBaseResults();const j=ensureJourney();const title=$('#modal .eyebrow');if(title)title.textContent='SEMESTER '+j.semester+' COMPLETE';const replay=$('#replay');if(state.finished&&replay){replay.insertAdjacentHTML('beforebegin',`<button class="primary" id="continueJourney">${j.semester<8?'Continue to semester '+(j.semester+1)+' →':'View my completed journey →'}</button>`);$('#continueJourney').onclick=()=>j.semester<8?startNextSemester():openStudentPhone('journey')}};
const journeyBaseLog=log;
log=function(text){journeyBaseLog(text==='Completed final exams. Semester one is in the books.'?`Completed semester ${ensureJourney().semester} finals.`:text)};
if(state)render();
